function scenicDetail(c,story,f,t,kit){const {rect,poly,noise}=kit;c.save();for(let i=0;i<18;i++){const x=i*29-12,y=208+noise(i,story.id)*45;if(['forest','flower','field'].includes(story.scene)){rect(c,x,y,4,8,'#263d39');rect(c,x-3,y+2,10,3,'#658268')}else if(['lab','power','city','theatre'].includes(story.scene)){rect(c,x,y,18,1,'#677485');rect(c,x+18,y,1,8,'#26394c')}else{rect(c,x,y,7,2,'#86938c');rect(c,x+3,y+3,3,1,'#384c60')}}if(['forest','flower'].includes(story.scene)){kit.tree(c,-6,275,2.4,['#172f30','#284c3e','#3d6650']);kit.tree(c,490,275,2.4,['#172f30','#284c3e','#3d6650'])}if(['temple','ruins','crystal','origin'].includes(story.scene)){kit.pillar(c,12,280,160,'#3c4e60');kit.pillar(c,470,280,160,'#3c4e60')}c.restore()}
function camera(c,shot,reduced){const p=smooth(shot.progress),from=shot.camera.from,to=shot.camera.to,scale=reduced?from[2]:mix(from[2],to[2],p),x=mix(from[0],to[0],reduced?.5:p),y=mix(from[1],to[1],reduced?.5:p);c.translate(240,135);c.scale(scale,scale);c.translate(-x,-y)}
